                RxOpts a; a.age = p == RP_MATHS ? AGE_FAR_FUTURE : (p == RP_SYNTHETIC ? AGE_FUTURISTIC : AGE_INDUSTRIAL);
                judge(RADIO_PROGRAMME_NAMES[p], renderProgramme(w, p, 8.0, nullptr, nullptr, a));
